const d=$input.first().json;
const miss=[];
if(!d.briefing)miss.push('briefing aprobado');
if(!d.design_option)miss.push('opcion de diseno seleccionada');
if(!d.cost_estimate)miss.push('estimacion de costes');
if(!d.trade_assignments||!d.trade_assignments.length)miss.push('asignacion de gremios');
const ok=miss.length===0;
return[{json:{...d,preflight_passed:ok,missing_items:miss}}];

const dbPrompt=$input.first().json;
const d=$('Preflight Check').first().json;
const b=d.briefing||{};
const des=d.design_option||{};
const ce=d.cost_estimate||{};
const trades=d.trade_assignments||[];
const budget=d.budget_target?d.budget_target+'€'+(d.budget_flexible?' (flexible)':''):'No especificado';
const obj=Array.isArray(b.objectives)?b.objectives.join(', '):(b.objectives||'?');
const needs=Array.isArray(b.client_needs)?b.client_needs.join(', '):(b.client_needs||'?');
const rooms=Array.isArray(b.rooms_affected)?b.rooms_affected.join(', '):(b.rooms_affected||'?');
const tradesText=trades.map(t=>(t.trade_type||'?')+': '+(t.scope_description||'pendiente')).join(' | ');
const schema=JSON.stringify({title:'Propuesta de Reforma — nombre proyecto',executive_summary:'resumen ejecutivo 2-3 parrafos',scope_description:'alcance detallado por especialidad y espacio',total_price:0,payment_conditions:'ej: 30% al inicio, 40% a mitad, 30% a la entrega',estimated_duration:'ej: 8-10 semanas',inclusions:['item incluido 1'],exclusions:['item excluido 1']});
const ps_fallback='Eres el asistente de redaccion de un estudio de arquitectura en Espana. Genera propuestas comerciales profesionales. Responde SOLO con JSON valido, sin texto adicional antes ni despues.';
// === STUDIO PROFILE INJECTION (B23) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_tone=_safeStudio(_studio.tone)||{},_priorities=_safeStudio(_studio.priorities)||[],_redLines=_safeStudio(_studio.red_lines)||[];
const _toneCli=_tone.clientes||{};
const _SP_PROP_LINES=[];
_SP_PROP_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'. Persona principal: '+(_id.persona_principal||'arquitecto')+'.');
_SP_PROP_LINES.push('TONO de la propuesta al cliente: '+(_toneCli.formalidad||'cercano')+', '+(_toneCli.tecnicidad||'llano')+', '+(_toneCli.longitud||'conciso')+(_toneCli.tutea?'. Tutea por defecto.':'. Usa usted por defecto.')+(_toneCli.explica_terminos?' Explica terminos tecnicos entre parentesis.':''));
_SP_PROP_LINES.push('PRIORIDADES (orden estricto, reflejarlas en el executive_summary y scope_description):');
(_priorities||[]).forEach(p=>_SP_PROP_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')+(p.detalle?' - '+p.detalle:'')));
_SP_PROP_LINES.push('LINEAS ROJAS (NUNCA prometer ni proponer):');
(_redLines||[]).forEach(l=>_SP_PROP_LINES.push('- '+(l.texto||'')));
_SP_PROP_LINES.push('REGLA: Si el alcance que viene del briefing/design contradice una linea roja, marcalo en el executive_summary y NO lo incluyas en inclusions.');
const _SP_PROP=_SP_PROP_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
const ps = _SP_PROP + '\n\n' + ((dbPrompt && dbPrompt.content) ? dbPrompt.content : ps_fallback);
const pu='Genera una propuesta comercial completa para este proyecto.\n\nPROYECTO: '+d.project_name+'\nTipo: '+d.project_type+' | '+d.property_area_m2+' m2 | '+d.location_city+(d.location_province?', '+d.location_province:'')+' | Urgencia: '+(d.urgency||'Normal')+'\nPresupuesto cliente: '+budget+'\n\nCLIENTE: '+d.client_name+'\n\nOBJETIVOS: '+obj+'\nNECESIDADES: '+needs+'\nESPACIOS: '+rooms+'\n\nDISENO: '+(des.option_name||'Pendiente')+(des.description?'\n'+des.description:'')+' | TOTAL ESTIMADO: '+(ce.total_estimated?ce.total_estimated+'€':'Pendiente')+'\n\nGREMIOS: '+(tradesText||'Pendiente')+'\n\nEstructura JSON requerida:\n'+schema;
return[{json:{...d,prompt_system:ps,prompt_user:pu,model:'gpt-4o',temperature:0.4,project_id:d.id,agent_name:'agent_proposal'}}];

const llm=$input.first().json;
const proj=$('Load Project + Client').first().json;
const ce=proj.cost_estimate||{};
let parsed={};
if(llm.status!=='error'){
  try{const m=(llm.text||'').match(/\{[\s\S]*\}/);if(m)parsed=JSON.parse(m[0]);}catch(e){}
}
return[{json:{
  ...proj,
  status:llm.status||'ok',
  error_message:llm.error_message||null,
  title:parsed.title||('Propuesta — '+proj.project_name),
  executive_summary:parsed.executive_summary||'[Generacion automatica fallida — revisar manualmente]',
  scope_description:parsed.scope_description||'',
  total_price:parsed.total_price||ce.total_estimated||0,
  payment_conditions:parsed.payment_conditions||'A definir',
  estimated_duration:parsed.estimated_duration||'A definir',
  inclusions:JSON.stringify(parsed.inclusions||[]),
  exclusions:JSON.stringify(parsed.exclusions||[])
}}];

const w=$input.first().json;
const saved=$('Save Draft').first().json;
const expectedToken=saved.webhook_token||'';
const receivedToken=(w.query&&w.query.token)||(w.body&&w.body.token)||w.token||'';
const tokenValid=!!expectedToken&&receivedToken===expectedToken;
const rawDecision=(w.query&&w.query.decision)||(w.body&&w.body.decision)||w.decision||'unknown';
const decision=tokenValid?rawDecision:'rejected';
return[{json:{...w,decision:decision,approved:tokenValid&&decision==='approved',token_valid:tokenValid,project_id:$('Load Project + Client').first().json.id}}];
